  vec3 col2 = vec3(0.2,0.6,0.6);
  vec3 col3 = vec3(0.6,0.6,0.2);
  for(int i = 0;i<8;i++){
    p = abs(p)-0.2;
    p.xy *= rot(sct);
    p.xz *= rot(sct);
    p.yz *= rot(sct);
    if(p.x<p.y&&p.x<p.z){acol += col1;}
    else if(p.y<p.z){acol += col2;}
    else{acol += col3;}
  }

  float d = length(p)-0.2;
  d = crobox(p,0.05);
  vec3 col =1.*acol*exp(-3.0*d);
