    dist(p+e.xyy,1.).w-dist(p-e.xyy,1.).w,
    dist(p+e.yxy,1.).w-dist(p-e.yxy,1.).w,
    dist(p+e.yyx,1.).w-dist(p-e.yyx,1.).w
    ));
}
